// Idiomas do app. O texto em português é a chave; L.T("texto") devolve a tradução do idioma atual
// (ou o próprio português, se faltar tradução).
static class L
{
    public static readonly string[] Codes = { "pt", "en", "es", "fr", "de" };
    public static readonly string[] NativeNames = { "Português", "English", "Español", "Français", "Deutsch" };
    public static string Code = "pt";

    // "" = automático (idioma do Windows; se não for um dos suportados, inglês)
    public static void Set(string setting)
    {
        string c = setting;
        if (string.IsNullOrEmpty(c) || Array.IndexOf(Codes, c) < 0)
        {
            c = CultureInfo.CurrentUICulture.TwoLetterISOLanguageName;
            if (Array.IndexOf(Codes, c) < 0) c = "en";
        }
        Code = c;
    }

    static Dictionary<string, string[]> map;

    public static string T(string pt)
    {
        if (pt == null || Code == "pt") return pt;
        if (map == null)
        {
            var m = new Dictionary<string, string[]>();
            foreach (var row in Data) m[row[0]] = row;
            map = m;
        }
        string[] r;
        int i = Array.IndexOf(Codes, Code);
        return i > 0 && map.TryGetValue(pt, out r) && i < r.Length && !string.IsNullOrEmpty(r[i]) ? r[i] : pt;
    }

