        new[] { "\"Posicionar clicando\": clique onde deve ficar o canto superior esquerdo do bloco. As setas levam o bloco para um dos cantos.", "\"Place by clicking\": click where the block's top-left corner should be. The arrows move the block to a corner.", "\"Colocar haciendo clic\": haz clic donde debe quedar la esquina superior izquierda del bloque. Las flechas lo llevan a una esquina.", "« Placer en cliquant » : cliquez où doit être le coin supérieur gauche du bloc. Les flèches l'envoient dans un coin.", "„Per Klick platzieren“: dorthin klicken, wo die linke obere Ecke des Blocks sein soll. Die Pfeile schieben ihn in eine Ecke." },
        new[] { "Atalhos (funcionam dentro do jogo)", "Shortcuts (work in game)", "Atajos (funcionan en el juego)", "Raccourcis (fonctionnent en jeu)", "Tastenkürzel (funktionieren im Spiel)" },
        new[] { "Anotar rápido", "Quick note", "Nota rápida", "Note rapide", "Schnellnotiz" },
        new[] { "Mostrar/ocultar senhas", "Show/hide codes", "Mostrar/ocultar claves", "Afficher/masquer les codes", "Codes ein/aus" },
